import fs from "node:fs";
import path from "node:path";

const buildNumber = String(process.env.VITE_BUILD_NUMBER || process.env.GITHUB_RUN_NUMBER || "").trim();
const buildSha = String(process.env.VITE_BUILD_SHA || process.env.GITHUB_SHA || "").trim();
const builtAt = buildNumber || buildSha ? new Date().toISOString() : "";

const outputDir = path.resolve("client/generated");
const outputFile = path.join(outputDir, "buildInfo.ts");

fs.mkdirSync(outputDir, { recursive: true });
fs.writeFileSync(
  outputFile,
  [
    "// Auto-generated by scripts/generate-build-info.mjs",
    `export const BUILD_NUMBER = ${JSON.stringify(buildNumber)};`,
    `export const BUILD_SHA = ${JSON.stringify(buildSha)};`,
    `export const BUILD_AT = ${JSON.stringify(builtAt)};`,
    "",
  ].join("\n"),
);
